af = [
  {"id":"water","names":["Water","Aqua","Eau"],"risk":"green","category":"Solvent","purpose":"Universal solvent and base ingredient in most cosmetic formulations, making up 50-90% of most products.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Water is the most common cosmetic ingredient, serving as the primary solvent and delivery system for other ingredients. It hydrates the skin on contact and forms the base of most serums, lotions, and creams.","description_th":"น้ำเป็นส่วนผสมเครื่องสำอางที่พบมากที่สุด ทำหน้าที่เป็นตัวทำละลายหลักและช่วยส่งมอบส่วนผสมอื่นๆ ให้ผิวหนัง มักพบเป็นส่วนผสมหลักในเซรั่ม โลชั่น และครีมส่วนใหญ่"},
  {"id":"adenosine","names":["Adenosine"],"risk":"green","category":"Anti-aging","purpose":"Naturally occurring molecule that helps smooth fine lines and reduce inflammation in skin.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Adenosine is a naturally occurring molecule found in all living cells. In cosmetics, it acts as an anti-aging ingredient that helps reduce fine lines, wrinkles, and skin inflammation. It is considered very safe and well-tolerated.","description_th":"อะดีโนซีนเป็นโมเลกุลที่เกิดขึ้นตามธรรมชาติในเซลล์ที่มีชีวิตทุกชนิด ในเครื่องสำอางช่วยต้านริ้วรอย ลดเส้นละเอียดและการอักเสบของผิว ถือว่าปลอดภัยมากและผิวส่วนใหญ่ทนได้ดี"},
  {"id":"alcohol-denat","names":["Alcohol Denat","Denatured Alcohol","SD Alcohol"],"risk":"yellow","category":"Solvent","purpose":"Denatured ethanol used as solvent, antiseptic, and to create a lightweight fast-drying texture.","concerns":["Can strip natural skin oils","May cause dryness and irritation with frequent use","Can disrupt skin barrier in sensitive skin"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Alcohol Denat is ethanol that has been rendered undrinkable. It helps products spread, acts as an antiseptic, and evaporates quickly leaving a clean feel. However, frequent use can disrupt the skin barrier and cause dryness, especially in sensitive skin.","description_th":"แอลกอฮอล์ เดนาท์ เป็นเอทานอลที่ถูกทำให้ดื่มไม่ได้ ช่วยให้ผลิตภัณฑ์กระจายตัวได้ดีและระเหยไวให้ความรู้สึกสะอาด แต่การใช้บ่อยอาจทำลายเกราะป้องกันผิวและทำให้แห้งได้"},
  {"id":"allantoin","names":["Allantoin"],"risk":"green","category":"Skin Conditioner","purpose":"Soothing, healing ingredient that promotes cell renewal and helps calm irritated skin.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Allantoin is a natural compound found in plants like comfrey that promotes skin cell renewal, soothes irritation, and has anti-inflammatory properties. It is extremely well-tolerated and suitable for all skin types including sensitive skin.","description_th":"อัลแลนโทอินเป็นสารประกอบธรรมชาติที่พบในพืชอย่างคอมเฟร ช่วยส่งเสริมการต่ออายุเซลล์ผิว บรรเทาการระคายเคือง และมีคุณสมบัติต้านการอักเสบ รองรับผิวทุกประเภทรวมถึงผิวบอบบาง"},
  {"id":"aloe-vera","names":["Aloe Barbadensis Leaf Juice","Aloe Vera Gel","Aloe Vera"],"risk":"green","category":"Botanical Extract","purpose":"Hydrating, soothing plant extract with anti-inflammatory and wound-healing properties.","concerns":["Rare allergy in latex-sensitive individuals"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Aloe Vera juice extracted from the Aloe Barbadensis plant is rich in polysaccharides, vitamins, and minerals. It soothes sunburns, provides hydration, and helps heal minor skin irritations.","description_th":"น้ำว่านหางจระเข้อุดมด้วยโพลีแซ็กคาไรด์ วิตามิน และแร่ธาตุ ช่วยบรรเทาแสบร้อนจากแดด ให้ความชุ่มชื้น และช่วยรักษาการระคายเคืองผิวเล็กน้อย"},
  {"id":"alpha-arbutin","names":["Alpha-Arbutin","a-Arbutin"],"risk":"green","category":"Skin Brightener","purpose":"Stable brightening ingredient that inhibits melanin production to reduce dark spots.","concerns":["Mild irritation at high concentrations"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Alpha-Arbutin is a stable synthetic derivative of hydroquinone that inhibits tyrosinase to reduce melanin production. It is effective at brightening dark spots with a much better safety profile than hydroquinone.","description_th":"อัลฟา-อาร์บูตินเป็นอนุพันธ์สังเคราะห์ที่เสถียรของไฮโดรควิโนน ยับยั้งไทโรซิเนสเพื่อลดการผลิตเมลานิน มีประสิทธิภาพในการทำให้ผิวสว่างขึ้น"},
  {"id":"alpha-isomethyl-ionone","names":["Alpha-Isomethyl Ionone","Isomethyl Ionone"],"risk":"yellow","category":"Fragrance","purpose":"Synthetic violet-like fragrance compound.","concerns":["Known EU fragrance allergen","May cause contact dermatitis"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Alpha-Isomethyl Ionone is a synthetic fragrance with a violet-like scent. It is listed as one of the 26 EU fragrance allergens that must be declared on product labels.","description_th":"อัลฟา-ไอโซเมทิล ไอโอโนนเป็นน้ำหอมสังเคราะห์ที่มีกลิ่นคล้ายไวโอเล็ต ถูกระบุเป็นหนึ่งใน 26 สารก่อภูมิแพ้ในน้ำหอมของสหภาพยุโรป"},
  {"id":"aluminum-chlorohydrate","names":["Aluminum Chlorohydrate","ACH"],"risk":"yellow","category":"Antiperspirant","purpose":"Active antiperspirant ingredient that temporarily blocks sweat glands.","concerns":["Potential hormonal disruption (debated)","May cause skin irritation","Avoid on broken skin"],"kidsUnsafe":False,"pregnancyWarning":True,"description_en":"Aluminum Chlorohydrate is the most common active ingredient in antiperspirants. It forms a gel plug in sweat ducts. Regulatory bodies consider it safe at approved concentrations though debates exist around potential hormonal effects.","description_th":"อะลูมิเนียมคลอโรไฮเดรตเป็นส่วนผสมออกฤทธิ์ที่พบบ่อยในยาระงับเหงื่อ ทำงานโดยสร้างก้อนเจลในท่อเหงื่อ ยังมีการถกเถียงเกี่ยวกับผลกระทบต่อฮอร์โมน"},
  {"id":"argan-oil","names":["Argan Oil","Argania Spinosa Kernel Oil"],"risk":"green","category":"Emollient","purpose":"Luxurious plant oil rich in fatty acids and Vitamin E that moisturizes skin and hair.","concerns":["May cause breakouts in acne-prone skin"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Argan Oil from the Moroccan Argan tree is rich in oleic and linoleic fatty acids, Vitamin E, and antioxidants. It deeply moisturizes, reduces inflammation, and improves skin elasticity.","description_th":"น้ำมันอาร์แกนจากต้นอาร์แกนของโมร็อกโก อุดมด้วยกรดไขมัน วิตามินอี และสารต้านอนุมูลอิสระ ให้ความชุ่มชื้นลึก ลดการอักเสบ และเพิ่มความยืดหยุ่นให้ผิว"},
  {"id":"ascorbic-acid","names":["Ascorbic Acid","Vitamin C","L-Ascorbic Acid"],"risk":"green","category":"Antioxidant","purpose":"Potent antioxidant that brightens skin, boosts collagen, and protects against UV damage.","concerns":["Unstable and oxidizes quickly","Can cause mild irritation on sensitive skin"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Ascorbic Acid is the purest form of Vitamin C, a powerful antioxidant that neutralizes free radicals, stimulates collagen synthesis, and inhibits melanin production for brighter skin. It is highly effective but unstable.","description_th":"กรดแอสคอร์บิกเป็นวิตามินซีในรูปแบบที่บริสุทธิ์ที่สุด ต้านอนุมูลอิสระอย่างทรงพลัง กระตุ้นการสังเคราะห์คอลลาเจน และยับยั้งการผลิตเมลานิน"},
  {"id":"ascorbyl-glucoside","names":["Ascorbyl Glucoside"],"risk":"green","category":"Antioxidant","purpose":"Stable Vitamin C derivative that brightens skin and provides antioxidant protection.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Ascorbyl Glucoside is a stable form of Vitamin C where ascorbic acid is bonded to glucose. More stable and less irritating than pure Ascorbic Acid, making it suitable for sensitive skin.","description_th":"อะสคอร์บิล กลูโคไซด์เป็นวิตามินซีรูปแบบที่เสถียร เสถียรและระคายเคืองน้อยกว่าวิตามินซีบริสุทธิ์ เหมาะสำหรับผิวบอบบาง"},
  {"id":"avobenzone","names":["Avobenzone","Butyl Methoxydibenzoylmethane","Parsol 1789"],"risk":"yellow","category":"UV Filter","purpose":"Chemical UVA sunscreen filter that absorbs UVA rays to protect against sun damage.","concerns":["Degrades in sunlight without stabilizers","May cause irritation","Potential endocrine disruption under study"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Avobenzone is the most widely used UVA filter in chemical sunscreens. It is photounstable and often combined with stabilizers like Octocrylene.","description_th":"อะโวเบนโซนเป็นตัวกรอง UVA ที่ใช้กันแพร่หลายในครีมกันแดดเคมี ดูดซับรังสี UVA แต่ไม่เสถียรเมื่อถูกแสง มักใช้ร่วมกับสารทำให้เสถียร"},
  {"id":"azelaic-acid","names":["Azelaic Acid","Nonanedioic Acid"],"risk":"green","category":"Exfoliant","purpose":"Multi-tasking acid that treats acne, rosacea, and hyperpigmentation gently.","concerns":["Mild tingling initially","Avoid contact with eyes"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Azelaic Acid is a naturally occurring dicarboxylic acid found in grains. It has antimicrobial, anti-inflammatory, and skin-brightening properties. It is FDA-approved for acne and rosacea and is considered safe during pregnancy.","description_th":"กรดอะเซเลอิกพบในธัญพืชตามธรรมชาติ มีคุณสมบัติต้านเชื้อโรค ต้านการอักเสบ และทำให้ผิวสว่างขึ้น ได้รับการอนุมัติจาก FDA สำหรับสิวและโรคโรซาเซีย ปลอดภัยระหว่างตั้งครรภ์"},
  {"id":"beeswax","names":["Beeswax","Cera Alba"],"risk":"green","category":"Emollient","purpose":"Natural wax that provides structure to balms and lipsticks while locking in moisture.","concerns":["Not vegan","Rare reactions in bee-allergic individuals"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Beeswax is a natural wax produced by honeybees. It thickens and solidifies formulas like lip balms while forming a protective barrier on skin that seals in moisture.","description_th":"ขี้ผึ้งเป็นขี้ผึ้งธรรมชาติที่ผลิตโดยผึ้ง ใช้ทำให้ผลิตภัณฑ์ข้นหนืดและสร้างชั้นป้องกันบนผิวที่กักเก็บความชุ่มชื้น"},
  {"id":"benzalkonium-chloride","names":["Benzalkonium Chloride","BAC"],"risk":"red","category":"Preservative","purpose":"Antimicrobial preservative used in eye drops and some skincare products.","concerns":["Strong irritant to eyes","Can damage skin barrier","Linked to antimicrobial resistance"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"Benzalkonium Chloride is a potent antimicrobial preservative. It can be irritating to skin and eyes and damages the skin barrier with repeated exposure. Should be avoided in products near eyes.","description_th":"เบนซาลโคเนียม คลอไรด์เป็นสารกันเสียต้านเชื้อโรคที่มีฤทธิ์แรง สามารถระคายเคืองผิวและดวงตา ทำลายเกราะป้องกันผิวเมื่อสัมผัสซ้ำๆ"},
  {"id":"benzophenone-3","names":["Benzophenone-3","Oxybenzone","BP-3"],"risk":"red","category":"UV Filter","purpose":"Chemical sunscreen filter that absorbs both UVA and UVB radiation.","concerns":["Endocrine disruptor","Detected in blood and breast milk","Coral reef damage - banned in Hawaii","Potential reproductive toxicity"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"Oxybenzone is widely used in sunscreens but has raised significant safety concerns. Studies show it is absorbed through skin into the bloodstream and acts as an endocrine disruptor. It is banned in Hawaii due to coral reef damage.","description_th":"เบนโซฟีโนน-3 (ออกซีเบนโซน) ใช้กันแพร่หลายในครีมกันแดด แต่มีข้อกังวลด้านความปลอดภัยอย่างมาก ถูกดูดซึมผ่านผิวเข้าสู่กระแสเลือดและรบกวนฮอร์โมน ถูกห้ามในฮาวาย"},
  {"id":"benzoyl-peroxide","names":["Benzoyl Peroxide","BPO"],"risk":"yellow","category":"Antimicrobial","purpose":"Antimicrobial agent that treats acne by killing C. acnes bacteria.","concerns":["Can bleach fabrics","May cause dryness and peeling","Avoid contact with eyes"],"kidsUnsafe":False,"pregnancyWarning":True,"description_en":"Benzoyl Peroxide is an effective OTC acne treatment that releases oxygen to kill acne-causing bacteria. It can cause dryness and peeling especially when starting treatment.","description_th":"เบนโซอิล เปอร์ออกไซด์เป็นยาแก้สิวที่ไม่ต้องใบสั่งแพทย์ ทำงานโดยปล่อยออกซิเจนเพื่อฆ่าแบคทีเรีย อาจทำให้แห้งและลอกโดยเฉพาะเมื่อเริ่มใช้"},
  {"id":"beta-glucan","names":["Beta-Glucan","Oat Beta-Glucan"],"risk":"green","category":"Skin Conditioner","purpose":"Powerful humectant from oats or yeast that deeply moisturizes and soothes skin.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Beta-Glucan is a naturally occurring polysaccharide found in oats and yeast. In skincare, it provides intense hydration, stimulates collagen, and has powerful anti-inflammatory effects.","description_th":"เบตากลูแคนเป็นโพลีแซ็กคาไรด์ที่เกิดขึ้นตามธรรมชาติในข้าวโอ๊ตและยีสต์ ให้ความชุ่มชื้นเข้มข้น กระตุ้นการผลิตคอลลาเจน และต้านการอักเสบ"},
  {"id":"bha","names":["BHA","Butylated Hydroxyanisole"],"risk":"red","category":"Antioxidant Preservative","purpose":"Synthetic antioxidant preservative used in cosmetics.","concerns":["Possible carcinogen (IARC Group 2B)","Endocrine disrupting properties","Banned in EU food"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"Butylated Hydroxyanisole (BHA) is a synthetic antioxidant classified as a possible human carcinogen by the IARC. It has demonstrated endocrine-disrupting activity in animal studies and is best avoided.","description_th":"บิวทิเลต ไฮดรอกซีอะนีโซล (BHA) จัดเป็นสารก่อมะเร็งในมนุษย์ที่เป็นไปได้โดย IARC และแสดงคุณสมบัติรบกวนต่อมไร้ท่อในการศึกษาในสัตว์"},
  {"id":"bht","names":["BHT","Butylated Hydroxytoluene"],"risk":"yellow","category":"Antioxidant Preservative","purpose":"Synthetic antioxidant used to prevent rancidity in cosmetics.","concerns":["Potential endocrine disruptor","May cause skin sensitization"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"BHT is a synthetic antioxidant used in cosmetics. At cosmetic concentrations, it is generally considered safe. However, there are some concerns about potential endocrine disruption at higher exposures.","description_th":"BHT เป็นสารต้านอนุมูลอิสระสังเคราะห์ ในความเข้มข้นที่ใช้ในเครื่องสำอางถือว่าปลอดภัยโดยทั่วไป แต่มีข้อกังวลเกี่ยวกับการรบกวนต่อมไร้ท่อ"},
  {"id":"bisabolol","names":["Bisabolol","Alpha-Bisabolol"],"risk":"green","category":"Skin Conditioner","purpose":"Natural compound from chamomile that soothes, heals, and reduces skin irritation.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Alpha-Bisabolol is found primarily in chamomile essential oil. It has potent anti-inflammatory, skin-soothing, and wound-healing properties and is extremely well-tolerated.","description_th":"อัลฟา-บิสาโบลอลพบในน้ำมันหอมระเหยคาโมมายล์เป็นหลัก มีคุณสมบัติต้านการอักเสบ บรรเทาผิว และรักษาแผลที่ทรงพลัง"},
  {"id":"bismuth-oxychloride","names":["Bismuth Oxychloride","CI 77163"],"risk":"yellow","category":"Colorant","purpose":"Pearlescent pigment in mineral makeup for silky, luminous finish.","concerns":["May cause itching","Can clog pores","Not for acne-prone skin"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Bismuth Oxychloride is a naturally occurring mineral compound used as a pearlescent pigment in mineral makeup. It gives products a silky, shimmery quality but is known to cause itching in some users.","description_th":"บิสมัท ออกซีคลอไรด์ใช้เป็นสีเรืองแสงในเครื่องสำอางแบบมิเนอรัล ให้ผลิตภัณฑ์มีลักษณะนวลและแวววาว แต่ทำให้คันในบางคน"},
  {"id":"boric-acid","names":["Boric Acid","Boracic Acid"],"risk":"red","category":"Preservative","purpose":"Antiseptic that is banned or restricted in many countries for cosmetic use.","concerns":["Toxic to reproductive system","Banned in EU cosmetics","Developmental toxicity"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"Boric Acid is banned or severely restricted in cosmetics in the EU and Canada due to reproductive toxicity. If found in a cosmetic product, it is a major red flag.","description_th":"กรดบอริกถูกห้ามหรือจำกัดการใช้อย่างเข้มงวดในเครื่องสำอางในสหภาพยุโรปและแคนาดา เนื่องจากความเป็นพิษต่อระบบสืบพันธุ์"},
  {"id":"butylene-glycol","names":["Butylene Glycol","1,3-Butanediol"],"risk":"green","category":"Humectant","purpose":"Versatile humectant and solvent that hydrates skin and enhances penetration.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Butylene Glycol is a small molecule diol used as a humectant, solvent, and penetration enhancer. It draws moisture to skin and helps active ingredients absorb more effectively.","description_th":"บิวทิลีน ไกลคอลเป็นไดออลโมเลกุลขนาดเล็กที่ใช้เป็นสารดึงดูดความชื้น ตัวทำละลาย และสารเพิ่มการซึมผ่าน"},
  {"id":"butylparaben","names":["Butylparaben"],"risk":"yellow","category":"Preservative","purpose":"Synthetic paraben preservative.","concerns":["Weak estrogenic activity","Endocrine disruption concerns","Restricted in EU"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"Butylparaben has demonstrated weak estrogenic activity and has been detected in breast tumor tissue. The EU restricts its use. Products labeled paraben-free avoid this ingredient.","description_th":"บิวทิลพาราเบนแสดงฤทธิ์เอสโตรเจนอ่อนๆ และตรวจพบในเนื้อเยื่อเนื้องอกเต้านม สหภาพยุโรปจำกัดการใช้"},
  {"id":"caffeine","names":["Caffeine"],"risk":"green","category":"Antioxidant","purpose":"Antioxidant that reduces puffiness, dark circles, and has vasoconstrictive effects.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Caffeine is a naturally occurring stimulant found in coffee and tea. In skincare, it reduces under-eye puffiness by constricting blood vessels and is used in anti-cellulite treatments.","description_th":"คาเฟอีนจากกาแฟและชา ในผลิตภัณฑ์บำรุงผิวลดบวมใต้ตาโดยหดหลอดเลือดและใช้ในผลิตภัณฑ์ต้านเซลลูไลต์"},
  {"id":"camellia-sinensis-extract","names":["Camellia Sinensis Leaf Extract","Green Tea Extract","EGCG"],"risk":"green","category":"Antioxidant","purpose":"Potent antioxidant green tea extract that protects against UV damage and soothes inflammation.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Green Tea Extract is rich in polyphenol antioxidants, particularly EGCG. It protects skin from UV-induced damage, reduces inflammation, and controls sebum production.","description_th":"สารสกัดชาเขียวอุดมด้วยสารต้านอนุมูลอิสระโพลีฟีนอล ปกป้องผิวจาก UV ลดการอักเสบ และควบคุมการผลิตซีบัม"},
  {"id":"caprylic-capric-triglyceride","names":["Caprylic/Capric Triglyceride","MCT Oil"],"risk":"green","category":"Emollient","purpose":"Lightweight emollient from coconut oil that moisturizes without feeling greasy.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Caprylic/Capric Triglyceride is a fraction of coconut oil composed of medium-chain fatty acids. It spreads beautifully, provides non-greasy moisturizing, and is non-comedogenic.","description_th":"คาปริลิก/แคปริก ไตรกลีเซอไรด์เป็นส่วนหนึ่งของน้ำมันมะพร้าว กระจายตัวได้สวยงาม ให้ความชุ่มชื้นโดยไม่มัน และไม่อุดตันรูขุมขน"},
  {"id":"carbomer","names":["Carbomer","Carbopol"],"risk":"green","category":"Thickener","purpose":"Synthetic polymer used to thicken and give gel-like consistency to formulations.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Carbomer is a family of synthetic acrylic acid polymers used as thickeners and gelling agents. They create the smooth, gel-like texture in many serums and moisturizers.","description_th":"คาร์โบเมอร์เป็นกลุ่มโพลีเมอร์อะคริลิกแอซิดสังเคราะห์ ใช้เป็นสารทำให้ข้นหนืดและเจลในเซรั่มและมอยเจอไรเซอร์"},
  {"id":"ceramide-np","names":["Ceramide NP","Ceramide 3"],"risk":"green","category":"Skin Barrier","purpose":"Key skin barrier lipid that prevents moisture loss and maintains the natural moisture barrier.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Ceramide NP is one of the most important ceramides naturally found in skin. It maintains the skin barrier by filling gaps between skin cells and preventing transepidermal water loss.","description_th":"เซราไมด์ NP เป็นหนึ่งในเซราไมด์ที่สำคัญที่สุดในผิวหนังตามธรรมชาติ ช่วยรักษาเกราะป้องกันผิวและป้องกันการสูญเสียน้ำ"},
  {"id":"ceramide-ap","names":["Ceramide AP","Ceramide 6-II"],"risk":"green","category":"Skin Barrier","purpose":"Lipid that helps repair and maintain the skin barrier.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Ceramide AP is a phytoceramide that works synergistically with other ceramides to restore skin lipid layers. Particularly effective for eczema and dry skin conditions.","description_th":"เซราไมด์ AP เป็นไฟโตเซราไมด์ที่ทำงานร่วมกับเซราไมด์อื่นๆ เพื่อฟื้นฟูชั้นไขมันในผิว มีประสิทธิภาพสำหรับกลากและผิวแห้ง"},
  {"id":"cetearyl-alcohol","names":["Cetearyl Alcohol","Cetostearyl Alcohol"],"risk":"green","category":"Emollient","purpose":"Fatty alcohol that thickens and stabilizes creams while softening skin.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Cetearyl Alcohol is a mixture of fatty alcohols used as an emulsifier, thickener, and emollient. Despite the name, it does not dry out skin. It gives creams their smooth, stable texture.","description_th":"เซทีแอริล แอลกอฮอล์เป็นส่วนผสมของแอลกอฮอล์ไขมัน ใช้เป็นสารทำให้เข้ากัน สารทำให้ข้น และสารทำให้ผิวนวล ไม่ทำให้ผิวแห้งอย่างแอลกอฮอล์ทั่วไป"},
  {"id":"cetyl-alcohol","names":["Cetyl Alcohol","1-Hexadecanol"],"risk":"green","category":"Emollient","purpose":"Fatty alcohol used to thicken, stabilize, and soften cosmetic formulations.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Cetyl Alcohol is a saturated fatty alcohol from natural sources. It acts as a thickener, emulsifier, and emollient in creams and lotions. It is very gentle and non-drying.","description_th":"เซทิล แอลกอฮอล์เป็นแอลกอฮอล์ไขมันอิ่มตัวจากแหล่งธรรมชาติ ทำหน้าที่เป็นสารทำให้ข้น สารทำให้เข้ากัน และสารทำให้ผิวนวล อ่อนโยนมากและไม่ทำให้แห้ง"},
  {"id":"citric-acid","names":["Citric Acid"],"risk":"yellow","category":"pH Adjuster","purpose":"Natural acid from citrus fruits used to adjust pH and provide mild exfoliation.","concerns":["Can cause irritation at high concentrations","May increase sun sensitivity"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Citric Acid is a naturally occurring alpha-hydroxy acid in citrus fruits. In cosmetics it is used primarily to adjust pH levels. At higher concentrations it provides mild exfoliation.","description_th":"กรดซิตริกเป็นกรดอัลฟาไฮดรอกซีที่เกิดขึ้นตามธรรมชาติในผลไม้ตระกูลส้ม ในเครื่องสำอางใช้ปรับระดับ pH เป็นหลัก"},
  {"id":"coal-tar","names":["Coal Tar","Crude Coal Tar"],"risk":"red","category":"Active Ingredient","purpose":"Complex mixture for psoriasis/dandruff treatment, classified as carcinogen.","concerns":["Known human carcinogen (IARC Group 1)","Banned in EU cosmetics","Photosensitizing"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"Coal Tar is classified as a Group 1 known human carcinogen by the IARC and is banned in European cosmetics. Use only under medical supervision.","description_th":"น้ำมันดินถ่านหินถูกจัดเป็นสารก่อมะเร็งในมนุษย์กลุ่ม 1 โดย IARC และถูกห้ามในเครื่องสำอางยุโรป"},
  {"id":"cocamide-dea","names":["Cocamide DEA","Coconut Diethanolamide"],"risk":"red","category":"Surfactant","purpose":"Foaming agent from coconut oil, associated with cancer risk.","concerns":["Classified as possible carcinogen (IARC Group 2B)","Contaminated with nitrosamines"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"Cocamide DEA is classified as a possible carcinogen by the IARC due to nitrosamine contamination. California lists it as a known carcinogen.","description_th":"โคคาไมด์ DEA ถูกจัดเป็นสารก่อมะเร็งที่เป็นไปได้โดย IARC เนื่องจากการปนเปื้อนของไนโตรซามีน"},
  {"id":"cocamidopropyl-betaine","names":["Cocamidopropyl Betaine","CAPB"],"risk":"yellow","category":"Surfactant","purpose":"Mild surfactant from coconut oil used in gentle cleansers and baby products.","concerns":["Potential contact allergen","May cause skin sensitization"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Cocamidopropyl Betaine is a mild amphoteric surfactant much gentler than SLS. Widely used in baby products and sensitive skin cleansers. It has been identified as a potential contact allergen in some individuals.","description_th":"โคคาไมโดโพรพิล เบเทนเป็นสารลดแรงตึงผิวอ่อนโยนที่ใช้กันแพร่หลายในผลิตภัณฑ์เด็กและผลิตภัณฑ์สำหรับผิวบอบบาง แต่อาจทำให้เกิดการแพ้ในบางคน"},
  {"id":"coenzyme-q10","names":["Coenzyme Q10","Ubiquinone","CoQ10"],"risk":"green","category":"Antioxidant","purpose":"Powerful antioxidant that protects against free radicals and may reduce signs of aging.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Coenzyme Q10 is a naturally occurring antioxidant in every cell. In skincare it neutralizes free radicals and may reduce fine lines. Levels in skin decrease with age.","description_th":"โคเอนไซม์ Q10 เป็นสารต้านอนุมูลอิสระที่เกิดขึ้นตามธรรมชาติในทุกเซลล์ ช่วยต้านอนุมูลอิสระและอาจลดเส้นริ้วรอย ระดับในผิวลดลงตามอายุ"},
  {"id":"copper-peptide-ghk-cu","names":["Copper Peptide","GHK-Cu"],"risk":"green","category":"Peptide","purpose":"Naturally occurring peptide-copper complex that promotes collagen and repairs skin.","concerns":["May irritate when combined with Vitamin C"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Copper Peptide (GHK-Cu) promotes collagen and elastin synthesis, accelerates wound healing, and acts as an antioxidant. It is one of the most researched anti-aging peptides.","description_th":"คอปเปอร์ เปปไทด์ (GHK-Cu) ส่งเสริมการสังเคราะห์คอลลาเจนและอีลาสติน เร่งการรักษาแผล เป็นหนึ่งในเปปไทด์ต้านการแก่ชราที่ได้รับการศึกษามากที่สุด"},
  {"id":"cyclomethicone","names":["Cyclomethicone","Cyclosiloxane","D5"],"risk":"yellow","category":"Silicone","purpose":"Cyclic silicone that provides silky feel and helps other ingredients spread evenly.","concerns":["Bioaccumulation in environment","Restricted in EU wash-off products","Possible endocrine disruption"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Cyclomethicone is a mixture of cyclic silicones used for silky texture. D5 (Cyclopentasiloxane) is restricted in EU wash-off products due to environmental persistence.","description_th":"ไซโคลเมทิโคนเป็นส่วนผสมของซิลิโคนวงแหวน D5 ถูกจำกัดในผลิตภัณฑ์ล้างออกในสหภาพยุโรปเนื่องจากความเป็นอมตะในสิ่งแวดล้อม"},
  {"id":"d-panthenol","names":["D-Panthenol","Dexpanthenol","Provitamin B5"],"risk":"green","category":"Humectant","purpose":"Vitamin B5 precursor that deeply hydrates, soothes, and heals the skin barrier.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"D-Panthenol is the alcohol form of Pantothenic Acid (Vitamin B5). It is an excellent humectant, promotes skin barrier repair, soothes irritation, and accelerates wound healing.","description_th":"ดี-แพนทีนอลเป็นรูปแบบแอลกอฮอล์ของวิตามิน B5 เป็นสารดึงดูดความชื้นที่ยอดเยี่ยม ส่งเสริมการซ่อมแซมเกราะป้องกันผิวและเร่งการรักษาแผล"},
  {"id":"dimethicone","names":["Dimethicone","Polydimethylsiloxane","PDMS"],"risk":"green","category":"Silicone","purpose":"Silicone polymer that creates a smooth protective barrier on skin and hair.","concerns":["Non-biodegradable","Can cause acne in some users"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Dimethicone is a widely used synthetic silicone emollient. It creates a breathable barrier that locks in moisture without feeling heavy and is extensively used in hair care.","description_th":"ไดเมทิโคนเป็นโพลีเมอร์ซิลิโคนสังเคราะห์ที่ใช้กันอย่างแพร่หลาย สร้างชั้นป้องกันที่กักเก็บความชุ่มชื้นโดยไม่รู้สึกหนัก"},
  {"id":"dmdm-hydantoin","names":["DMDM Hydantoin"],"risk":"red","category":"Preservative","purpose":"Formaldehyde-releasing preservative used to prevent microbial contamination.","concerns":["Releases formaldehyde - a known carcinogen","Linked to hair loss","Allergic contact dermatitis"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"DMDM Hydantoin slowly releases formaldehyde to prevent microbial growth. Formaldehyde is a known carcinogen. It has been linked to allergic contact dermatitis and hair loss.","description_th":"DMDM ไฮแดนโทอินปล่อยฟอร์มาลดีไฮด์เพื่อป้องกันการเติบโตของเชื้อโรค ฟอร์มาลดีไฮด์เป็นสารก่อมะเร็ง เชื่อมโยงกับผิวหนังอักเสบจากการแพ้และผมร่วง"},
  {"id":"ethanol","names":["Ethanol","Ethyl Alcohol","Grain Alcohol"],"risk":"yellow","category":"Solvent","purpose":"Solvent and antimicrobial agent used in toners and sanitizers.","concerns":["Drying with frequent use","Disrupts skin microbiome","Damages skin barrier in sensitive skin"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Ethanol is used in cosmetics as a solvent and antimicrobial preservative. While effective, frequent use can disrupt the skin barrier and strip natural oils.","description_th":"เอทานอลใช้ในเครื่องสำอางเป็นตัวทำละลายและสารกันเสีย การใช้บ่อยอาจทำลายเกราะป้องกันผิวและดูดซับไขมันธรรมชาติ"},
  {"id":"ethylhexyl-methoxycinnamate","names":["Ethylhexyl Methoxycinnamate","Octinoxate","Octyl Methoxycinnamate"],"risk":"yellow","category":"UV Filter","purpose":"Chemical UVB filter used in sunscreens.","concerns":["Possible endocrine disruptor","Absorbed into bloodstream","Harmful to coral reefs - banned in Hawaii"],"kidsUnsafe":False,"pregnancyWarning":True,"description_en":"Octinoxate is the most widely used UVB filter globally. It is effective but studies have raised concerns about endocrine-disrupting activity. It is banned in Hawaii for harm to coral reefs.","description_th":"ออกทิโนเซตเป็นตัวกรอง UVB ที่ใช้กันแพร่หลายที่สุดในโลก มีประสิทธิภาพ แต่พบข้อกังวลเกี่ยวกับฤทธิ์รบกวนต่อมไร้ท่อ ถูกห้ามในฮาวาย"},
  {"id":"ethylhexylglycerin","names":["Ethylhexylglycerin"],"risk":"green","category":"Preservative Booster","purpose":"Multi-function ingredient that enhances preservative efficacy and conditions skin.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Ethylhexylglycerin is a glycerin-derived ingredient that enhances preservative efficacy and moisturizes skin, allowing products to use lower concentrations of harsh preservatives.","description_th":"เอทิลเฮกซิลไกลเซอรินเป็นส่วนผสมจากกลีเซอรีน ช่วยเพิ่มประสิทธิภาพสารกันเสียและให้ความชุ่มชื้นแก่ผิว"},
  {"id":"ferulic-acid","names":["Ferulic Acid"],"risk":"green","category":"Antioxidant","purpose":"Plant-based antioxidant that protects against UV damage and boosts stability of Vitamins C and E.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Ferulic Acid is a potent plant-based antioxidant that dramatically boosts the stability and effectiveness of Vitamins C and E. The combination of C + E + Ferulic Acid is considered a gold standard anti-aging formula.","description_th":"กรดเฟอรูลิกเป็นสารต้านอนุมูลอิสระจากพืช มีชื่อเสียงในการเพิ่มความเสถียรและประสิทธิภาพของวิตามิน C และ E สูตร C + E + Ferulic Acid ถือเป็นมาตรฐานทองคำ"},
  {"id":"formaldehyde","names":["Formaldehyde","Methanal","Formalin"],"risk":"red","category":"Preservative","purpose":"Preservative that is a known carcinogen. Banned in EU cosmetics.","concerns":["Known human carcinogen (IARC Group 1)","Strong skin sensitizer","Banned in EU cosmetics","May be hidden in formaldehyde-releasing preservatives"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"Formaldehyde is a known human carcinogen banned in EU cosmetics. It can be present indirectly through formaldehyde-releasing preservatives like DMDM Hydantoin.","description_th":"ฟอร์มาลดีไฮด์เป็นสารก่อมะเร็งในมนุษย์ที่ทราบกันดี ถูกห้ามในเครื่องสำอางในสหภาพยุโรป อาจปรากฏโดยอ้อมผ่านสารกันเสียที่ปล่อยฟอร์มาลดีไฮด์"},
  {"id":"fragrance","names":["Fragrance","Parfum","Aroma"],"risk":"yellow","category":"Fragrance","purpose":"Complex mixture of scent chemicals that may hide dozens of individual compounds.","concerns":["One of the most common causes of contact allergy","May contain undisclosed allergens","Can trigger migraines in sensitive individuals"],"kidsUnsafe":False,"pregnancyWarning":True,"description_en":"Fragrance is a catch-all term that can hide dozens to hundreds of individual chemicals. It is one of the most common allergens in cosmetics. The EU requires disclosure of 26 identified allergens above certain concentrations.","description_th":"น้ำหอม (พาร์ฟูม) เป็นคำรวมที่ซ่อนสารเคมีได้หลายสิบถึงหลายร้อยชนิด เป็นหนึ่งในสารก่อภูมิแพ้ที่พบบ่อยที่สุดในเครื่องสำอาง"},
  {"id":"glycerin","names":["Glycerin","Glycerol","Glycerine"],"risk":"green","category":"Humectant","purpose":"Highly effective humectant that draws moisture from the environment into the skin.","concerns":["May feel sticky at very high concentrations"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Glycerin is one of the most widely used and effective humectants in cosmetics. It draws water to skin, provides intense hydration, and strengthens the skin barrier.","description_th":"กลีเซอรีนเป็นสารดึงดูดความชื้นที่ใช้กันอย่างแพร่หลายและมีประสิทธิภาพสูงสุดในเครื่องสำอาง ดึงน้ำเข้าสู่ผิว ให้ความชุ่มชื้นอย่างเข้มข้น"}
]

g_l = [
  {"id":"galactomyces-ferment-filtrate","names":["Galactomyces Ferment Filtrate","GFF"],"risk":"green","category":"Ferment","purpose":"Yeast fermentation filtrate that brightens skin, minimizes pores, and improves texture.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Galactomyces Ferment Filtrate from yeast fermentation is rich in vitamins, minerals, and beta-glucan. It is famous for improving skin texture, brightening complexion, and minimizing pores.","description_th":"กาแลคโตไมซีส เฟอร์เมนต์ ฟิลเตรตจากการหมักยีสต์ อุดมด้วยวิตามิน แร่ธาตุ และเบตากลูแคน มีชื่อเสียงในการปรับปรุงเนื้อผิวและทำให้ผิวสว่างขึ้น"},
  {"id":"glycolic-acid","names":["Glycolic Acid","Hydroxyacetic Acid"],"risk":"yellow","category":"Exfoliant (AHA)","purpose":"The smallest AHA that penetrates deepest to exfoliate dead skin cells and stimulate collagen.","concerns":["Increases sun sensitivity","May cause irritation","Use SPF daily"],"kidsUnsafe":False,"pregnancyWarning":True,"description_en":"Glycolic Acid is the most widely studied AHA. Due to its small molecular weight, it penetrates deeply, exfoliates effectively, and stimulates collagen. Sun protection is essential.","description_th":"กรดไกลโคลิกเป็น AHA ที่ได้รับการศึกษามากที่สุด เนื่องจากน้ำหนักโมเลกุลน้อย จึงซึมลึก ผลัดเซลล์ผิว และกระตุ้นการสังเคราะห์คอลลาเจน ต้องใช้ครีมกันแดดเสมอ"},
  {"id":"glyceryl-stearate","names":["Glyceryl Stearate","GMS"],"risk":"green","category":"Emulsifier","purpose":"Plant-derived emulsifier that helps blend water and oil in creams and lotions.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Glyceryl Stearate is a naturally derived emulsifier made from glycerin and stearic acid. It stabilizes oil-in-water emulsions, giving creams their smooth texture.","description_th":"กลีเซอริล สเตียเรตเป็นสารทำให้เข้ากันที่ได้จากธรรมชาติ ช่วยทำให้อิมัลชันน้ำในน้ำมันในครีมและโลชั่นมีความเสถียร"},
  {"id":"glycyrrhiza-glabra-extract","names":["Glycyrrhiza Glabra Root Extract","Licorice Root Extract"],"risk":"green","category":"Botanical Extract","purpose":"Licorice-derived extract that brightens skin, reduces inflammation, and soothes.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Licorice Root Extract contains glabridin, which inhibits tyrosinase to reduce melanin production. It is one of the most effective plant-based brightening ingredients.","description_th":"สารสกัดรากชะเอมเทศมีกลาบริดินซึ่งยับยั้งไทโรซิเนสเพื่อลดการผลิตเมลานิน เป็นหนึ่งในส่วนผสมทำให้ผิวสว่างจากพืชที่มีประสิทธิภาพมากที่สุด"},
  {"id":"hyaluronic-acid","names":["Hyaluronic Acid","Sodium Hyaluronate","HA"],"risk":"green","category":"Humectant","purpose":"Powerfully hydrating molecule that holds up to 1000x its weight in water.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Hyaluronic Acid can hold up to 1000 times its weight in water. It plumps skin, reduces fine lines, and deeply hydrates. It is considered extremely safe and beneficial.","description_th":"กรดไฮยาลูโรนิกสามารถกักเก็บน้ำได้มากถึง 1,000 เท่าของน้ำหนักตัวเอง ทำให้ผิวอิ่มน้ำ ลดเส้นละเอียด และให้ความชุ่มชื้นอย่างลึกล้ำ"},
  {"id":"hydroquinone","names":["Hydroquinone","1,4-Benzenediol"],"risk":"red","category":"Skin Brightener","purpose":"Potent skin lightener that inhibits melanin production.","concerns":["Banned in EU cosmetics","Ochronosis with long-term use","Possible carcinogen","Requires medical supervision"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"Hydroquinone inhibits tyrosinase to reduce melanin. It is banned in cosmetics in the EU and Canada. Prolonged use can cause ochronosis (permanent skin discoloration).","description_th":"ไฮโดรควิโนนยับยั้งไทโรซิเนสเพื่อลดการผลิตเมลานิน ถูกห้ามในเครื่องสำอางในสหภาพยุโรปและแคนาดา การใช้ระยะยาวอาจทำให้เกิดออโครโนซิส"},
  {"id":"homosalate","names":["Homosalate"],"risk":"yellow","category":"UV Filter","purpose":"Chemical UVB filter in sunscreens.","concerns":["Possible endocrine disruptor","Absorbed into bloodstream"],"kidsUnsafe":False,"pregnancyWarning":True,"description_en":"Homosalate is a chemical UVB filter. The FDA has requested more safety data. Studies show it is absorbed into blood and has shown hormone-disrupting effects in lab studies.","description_th":"โฮโมซาเลตเป็นตัวกรอง UVB เคมี FDA ขอข้อมูลความปลอดภัยเพิ่มเติม ถูกดูดซึมเข้าสู่เลือดและรบกวนสัญญาณฮอร์โมนในการศึกษา"},
  {"id":"hydrolyzed-collagen","names":["Hydrolyzed Collagen","Collagen Peptides"],"risk":"green","category":"Protein","purpose":"Broken-down collagen that helps moisturize and strengthen skin.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Hydrolyzed Collagen is collagen that has been broken down into smaller peptide fragments. It moisturizes the skin surface, helps strengthen the skin, and may stimulate collagen production.","description_th":"ไฮโดรไลซ์ คอลลาเจนเป็นคอลลาเจนที่ถูกแบ่งเป็นชิ้นเปปไทด์ขนาดเล็ก ให้ความชุ่มชื้น เสริมความแข็งแรงให้ผิว และอาจกระตุ้นการผลิตคอลลาเจน"},
  {"id":"imidazolidinyl-urea","names":["Imidazolidinyl Urea","Germall 115"],"risk":"yellow","category":"Preservative","purpose":"Formaldehyde-releasing preservative that prevents bacterial growth.","concerns":["Releases formaldehyde","May cause contact dermatitis"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Imidazolidinyl Urea is a formaldehyde-releasing preservative. While the amounts of released formaldehyde are low at cosmetic concentrations, it can cause allergic contact dermatitis in sensitive individuals.","description_th":"อิมิดาโซลิดินิล ยูเรียเป็นสารกันเสียที่ปล่อยฟอร์มาลดีไฮด์ แม้ปริมาณน้อยแต่ยังอาจทำให้เกิดผิวหนังอักเสบจากการแพ้"},
  {"id":"iodopropynyl-butylcarbamate","names":["Iodopropynyl Butylcarbamate","IPBC"],"risk":"red","category":"Preservative","purpose":"Antifungal preservative restricted in many cosmetics due to toxicity.","concerns":["Banned in children under 3","Restricted in EU","Skin and eye irritant","Potential thyroid disruptor"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"IPBC is a powerful antifungal preservative. The EU restricts it to 0.02% in leave-on products and bans it from products for children under 3 and lip products.","description_th":"IPBC เป็นสารกันเสียต้านเชื้อราที่มีประสิทธิภาพ สหภาพยุโรปจำกัดที่ 0.02% และห้ามใช้ในผลิตภัณฑ์สำหรับเด็กอายุต่ำกว่า 3 ปี"},
  {"id":"isopropyl-alcohol","names":["Isopropyl Alcohol","IPA","Rubbing Alcohol"],"risk":"red","category":"Solvent","purpose":"Strong solvent and antiseptic, very drying to skin.","concerns":["Very drying","Disrupts skin microbiome","Damages skin barrier"],"kidsUnsafe":True,"pregnancyWarning":False,"description_en":"Isopropyl Alcohol is a common disinfectant. While effective as an antiseptic, it is extremely drying and can significantly damage the skin barrier with repeated use.","description_th":"ไอโซโพรพิล แอลกอฮอล์เป็นน้ำยาฆ่าเชื้อที่ทำให้แห้งมากและทำลายเกราะป้องกันผิวได้อย่างมีนัยสำคัญ"},
  {"id":"isopropyl-myristate","names":["Isopropyl Myristate","IPM"],"risk":"yellow","category":"Emollient","purpose":"Lightweight emollient that improves spreadability but is comedogenic.","concerns":["Highly comedogenic","May cause acne breakouts"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Isopropyl Myristate is a synthetic emollient that improves product spread. However, it is highly comedogenic (rated 5/5) and known to cause clogged pores and acne breakouts.","description_th":"ไอโซโพรพิล มิริสเตตเป็นสารทำให้ผิวนวลสังเคราะห์ มีความเสี่ยงสูงต่อการอุดตันรูขุมขน (ระดับ 5/5) ทำให้เกิดสิว"},
  {"id":"jojoba-oil","names":["Jojoba Oil","Simmondsia Chinensis Seed Oil"],"risk":"green","category":"Emollient","purpose":"Liquid wax similar to skin sebum that balances oil production and moisturizes.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Jojoba Oil is technically a liquid wax that closely resembles human sebum. It is non-comedogenic, balances sebum production, and is excellent for all skin types.","description_th":"น้ำมันโจโจบาเป็นขี้ผึ้งเหลวที่คล้ายคลึงกับซีบัมของมนุษย์มาก ไม่อุดตันรูขุมขน ปรับสมดุลการผลิตซีบัม เหมาะสำหรับผิวทุกประเภท"},
  {"id":"kaolin","names":["Kaolin","China Clay","Kaolin Clay"],"risk":"green","category":"Absorbent","purpose":"Natural clay mineral that absorbs excess oil and provides gentle exfoliation.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Kaolin is a naturally occurring white clay used in face masks and powder formulas. It absorbs excess sebum to mattify skin and gently exfoliates. Gentle enough for sensitive skin.","description_th":"เคาลินเป็นแร่ดินขาวที่เกิดขึ้นตามธรรมชาติ ใช้ในมาสก์หน้าและสูตรผง ดูดซับซีบัมส่วนเกินและผลัดเซลล์ผิวเบาๆ"},
  {"id":"kojic-acid","names":["Kojic Acid"],"risk":"yellow","category":"Skin Brightener","purpose":"Fungal-derived ingredient that inhibits melanin production to fade dark spots.","concerns":["May cause contact dermatitis","Restricted in EU (max 1%)"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Kojic Acid is produced by fungi during fermentation. It inhibits tyrosinase to reduce melanin production, making it effective at brightening skin. The EU restricts it to 1%.","description_th":"กรดโคจิกผลิตโดยเชื้อราระหว่างการหมัก ยับยั้งไทโรซิเนสเพื่อลดการผลิตเมลานิน สหภาพยุโรปจำกัดที่ 1%"},
  {"id":"lactic-acid","names":["Lactic Acid"],"risk":"yellow","category":"Exfoliant (AHA)","purpose":"Gentle AHA that exfoliates skin, improves texture, and acts as a humectant.","concerns":["Increases sun sensitivity","May irritate sensitive skin"],"kidsUnsafe":False,"pregnancyWarning":True,"description_en":"Lactic Acid is a naturally occurring AHA found in milk. It is one of the gentler AHAs, suitable for sensitive skin. It exfoliates and acts as a humectant, drawing moisture to skin.","description_th":"กรดแลคติกเป็น AHA ที่เกิดขึ้นตามธรรมชาติในนม เป็นหนึ่งใน AHA ที่อ่อนโยนกว่า เหมาะสำหรับผิวบอบบาง ผลัดเซลล์ผิวและดึงความชื้นเข้าสู่ผิว"},
  {"id":"lanolin","names":["Lanolin","Wool Fat","Wool Wax"],"risk":"yellow","category":"Emollient","purpose":"Natural wax from sheep that is one of the most effective skin barrier repair ingredients.","concerns":["Common allergen","Not vegan","Potential pesticide residues"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Lanolin is a natural wax from wool-bearing animals. It is an exceptional emollient that closely mimics the skin lipid barrier, ideal for severely dry skin. However, it is a known allergen.","description_th":"ลาโนลินเป็นขี้ผึ้งธรรมชาติจากสัตว์ที่มีขนแกะ เป็นสารทำให้ผิวนวลชั้นเยี่ยม แต่เป็นสารก่อภูมิแพ้ที่ทราบกันดี"},
  {"id":"lauryl-glucoside","names":["Lauryl Glucoside"],"risk":"green","category":"Surfactant","purpose":"Mild natural surfactant from coconut and corn, gentle enough for baby products.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Lauryl Glucoside is a mild alkyl polyglucoside surfactant from renewable plants. It is biodegradable, suitable for sensitive skin and baby products.","description_th":"ลอริล กลูโคไซด์เป็นสารลดแรงตึงผิวอ่อนโยนจากพืชทดแทนได้ สลายตัวทางชีวภาพได้ เหมาะสำหรับผิวบอบบางและผลิตภัณฑ์เด็ก"},
  {"id":"lead-acetate","names":["Lead Acetate","Lead(II) Acetate"],"risk":"red","category":"Colorant","purpose":"Lead compound formerly used in hair dyes. Banned in most countries.","concerns":["Highly toxic heavy metal","Known carcinogen","Neurotoxin","Banned in EU and Canada"],"kidsUnsafe":True,"pregnancyWarning":True,"description_en":"Lead Acetate is a highly toxic heavy metal compound formerly used as a hair colorant. It is banned in cosmetics in the EU and Canada. Any product containing it should be immediately discontinued.","description_th":"ตะกั่วอะซิเตตเป็นสารประกอบโลหะหนักพิษสูง ถูกห้ามในเครื่องสำอางในสหภาพยุโรปและแคนาดา หากพบในผลิตภัณฑ์ควรหยุดใช้ทันที"},
  {"id":"linalool","names":["Linalool"],"risk":"yellow","category":"Fragrance","purpose":"Naturally occurring fragrance compound found in lavender and many other plants.","concerns":["Listed as EU fragrance allergen","May cause contact dermatitis"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Linalool is a terpene alcohol found in many plants including lavender. It is listed as one of the 26 EU fragrance allergens and can cause contact dermatitis. Oxidized linalool is more allergenic.","description_th":"ลินาโลอลเป็นแอลกอฮอล์เทอร์พีนที่เกิดขึ้นตามธรรมชาติในพืชหลายชนิด ถูกระบุเป็นหนึ่งใน 26 สารก่อภูมิแพ้น้ำหอมของสหภาพยุโรป"},
  {"id":"linoleic-acid","names":["Linoleic Acid","Vitamin F"],"risk":"green","category":"Fatty Acid","purpose":"Essential omega-6 fatty acid that strengthens the skin barrier and benefits acne-prone skin.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Linoleic Acid is an essential omega-6 fatty acid found in plant oils like sunflower and rosehip oil. It is a key skin barrier lipid and beneficial for acne-prone skin.","description_th":"กรดไลโนเลอิกเป็นกรดไขมันจำเป็นโอเมก้า 6 พบในน้ำมันพืชอย่างทานตะวันและโรสฮิป เป็นส่วนประกอบสำคัญของเกราะป้องกันผิว"},
  {"id":"jojoba-esters","names":["Jojoba Esters"],"risk":"green","category":"Emollient","purpose":"Solid wax derived from jojoba oil providing a smooth, non-greasy skin feel.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Jojoba Esters are a hydrogenated form of jojoba oil in solid wax form. They provide excellent skin conditioning with a smooth, non-greasy texture.","description_th":"โจโจบา เอสเตอร์สเป็นน้ำมันโจโจบาที่ผ่านการเติมไฮโดรเจนในรูปแบบขี้ผึ้งแข็ง ให้ความรู้สึกผิวเนียนโดยไม่มัน"},
  {"id":"gluconolactone","names":["Glucono Delta Lactone","GDL","Gluconolactone"],"risk":"yellow","category":"Exfoliant (PHA)","purpose":"Gentle polyhydroxy acid (PHA) that exfoliates while providing antioxidant and humectant benefits.","concerns":["May cause mild irritation","Increases photosensitivity slightly"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Gluconolactone is a polyhydroxy acid (PHA) that provides gentle exfoliation similar to AHAs but with less irritation. It also acts as a humectant and antioxidant, making it suitable for sensitive skin.","description_th":"กลูโคโนแลกโตนเป็นกรดโพลีไฮดรอกซี (PHA) ที่ผลัดเซลล์ผิวเบาๆ คล้าย AHA แต่ระคายเคืองน้อยกว่า ยังทำหน้าที่เป็นสารดึงดูดความชื้นและสารต้านอนุมูลอิสระ เหมาะสำหรับผิวบอบบาง"},
  {"id":"green-tea-extract","names":["Green Tea Extract","Camellia Sinensis Extract","EGCG"],"risk":"green","category":"Antioxidant","purpose":"Rich antioxidant extract that protects skin from environmental damage and soothes inflammation.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Green Tea Extract is rich in catechins, particularly EGCG. It provides powerful antioxidant protection, reduces inflammation, and helps regulate sebum production.","description_th":"สารสกัดชาเขียวอุดมด้วยคาเทชินโดยเฉพาะ EGCG ให้การปกป้องต้านอนุมูลอิสระอย่างทรงพลัง ลดการอักเสบ และช่วยควบคุมการผลิตซีบัม"},
  {"id":"hydroxyethyl-cellulose","names":["Hydroxyethyl Cellulose","HEC","Natrosol"],"risk":"green","category":"Thickener","purpose":"Natural cellulose-derived thickener used in gels and lotions.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Hydroxyethyl Cellulose is a modified cellulose polymer used as a thickener and gelling agent. It is derived from natural cellulose and is biodegradable and safe for all skin types.","description_th":"ไฮดรอกซีเอทิล เซลลูโลสเป็นโพลีเมอร์เซลลูโลสที่ดัดแปลง ใช้เป็นสารทำให้ข้นและเจล ได้มาจากเซลลูโลสธรรมชาติ ปลอดภัยสำหรับผิวทุกประเภท"},
  {"id":"hydroxypropyl-methylcellulose","names":["Hydroxypropyl Methylcellulose","HPMC","Hypromellose"],"risk":"green","category":"Thickener","purpose":"Semi-synthetic cellulose polymer used to thicken and stabilize formulas.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Hydroxypropyl Methylcellulose is a semi-synthetic cellulose polymer widely used in cosmetics as a thickener and film-forming agent. It is considered very safe and is used in eye drops as well.","description_th":"ไฮดรอกซีโพรพิล เมทิลเซลลูโลสเป็นโพลีเมอร์เซลลูโลสกึ่งสังเคราะห์ ใช้เป็นสารทำให้ข้นและสารสร้างฟิล์มในเครื่องสำอาง ถือว่าปลอดภัยมากและใช้ในยาหยอดตาด้วย"},
  {"id":"lavender-oil","names":["Lavender Oil","Lavandula Angustifolia Oil"],"risk":"yellow","category":"Botanical Extract","purpose":"Aromatic plant oil with calming, anti-inflammatory, and antimicrobial properties.","concerns":["Potential allergen","Contains EU-listed allergens (linalool, linalyl acetate)","Some concerns about hormonal effects"],"kidsUnsafe":False,"pregnancyWarning":True,"description_en":"Lavender Essential Oil contains linalool and linalyl acetate, which are EU-listed allergens. It has antimicrobial and anti-inflammatory properties but can cause contact dermatitis. Studies have raised concerns about potential hormonal activity.","description_th":"น้ำมันหอมระเหยลาเวนเดอร์มีลินาโลอลและลินาลิล อะซิเตต ซึ่งเป็นสารก่อภูมิแพ้ในรายการสหภาพยุโรป มีคุณสมบัติต้านเชื้อโรคและต้านการอักเสบ แต่อาจทำให้เกิดผิวหนังอักเสบจากการแพ้"},
  {"id":"lecithin","names":["Lecithin","Soy Lecithin","Sunflower Lecithin"],"risk":"green","category":"Emollient","purpose":"Natural phospholipid that helps ingredients penetrate skin and provides hydration.","concerns":["Rare reactions in soy-allergic individuals"],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Lecithin is a natural phospholipid from egg yolks and soybeans. In cosmetics it acts as an emulsifier, emollient, and penetration enhancer, compatible with the skin lipid bilayer.","description_th":"เลซิตินเป็นสารประกอบฟอสโฟไลปิดธรรมชาติจากไข่แดงและถั่วเหลือง ทำหน้าที่เป็นสารทำให้เข้ากัน สารทำให้ผิวนวล และสารเพิ่มการซึมผ่าน เข้ากันได้กับชั้นไขมันของผิวหนัง"},
  {"id":"lysine","names":["Lysine","L-Lysine"],"risk":"green","category":"Amino Acid","purpose":"Essential amino acid that helps build collagen and strengthens the skin barrier.","concerns":[],"kidsUnsafe":False,"pregnancyWarning":False,"description_en":"Lysine is an essential amino acid and key building block of collagen. In cosmetics it strengthens the skin barrier, improves skin texture, and promotes wound healing.","description_th":"ไลซีนเป็นกรดอะมิโนจำเป็นที่เป็นองค์ประกอบสำคัญของคอลลาเจน ในเครื่องสำอางช่วยเสริมความแข็งแรงของเกราะป้องกันผิว ปรับปรุงเนื้อผิว และส่งเสริมการรักษาแผล"}
]

with open(os.path.join(base, 'ingredients_a_f.json'), 'w', encoding='utf-8') as f:
    json.dump(af, f, ensure_ascii=False, indent=2)
print(f'A-F: {len(af)} ingredients written')

